# Mirror top to below, clearing whatever was there originally
def mirror_clear_below(grid):
    """Mirror top section across separator, clear original bottom"""
    h = len(grid)
    mid = 5

    result = [[0]*15 for _ in range(h)]

    # Copy top section (including empty rows)
    for i in range(mid + 1):
        result[i] = grid[i][:]

    # Mirror non-empty rows from top to their positions
    for r in range(mid):
        m_r = mid * 2 - 1 - r  # 9-r

        if m_r < h:
            for c in range(15):
                color = grid[r][c]
                if color != 0:
                    result[m_r][c] = color

    return result

